find_rule:
js:
var d = [];
var res = request(input, {
  headers: {
    'User-Agent': 'Mozilla/5.0 (iPhone; CPU iPhone OS 16_0 like Mac OS X)',
    'Accept': 'application/json'
  }
});
try {
  var json = typeof res === 'string' ? JSON.parse(res) : res;
  var list = json.data?.list || json.items || json.data || [];
  for (var i = 0; i < list.length; i++) {
    var item = list[i];
    var title = item.title || item.name || '';
    var cover = item.cover || item.poster || item.pic || '';
    var id = item.id || item.vod_id || '';
    var desc = item.subtitle || item.remark || item.score || '';
    if (title && id) {
      d.push({
        title: title,
        desc: desc ? String(desc) : '',
        pic_url: cover ? cover + '@Referer=' + input : '',
        url: 'https://api.example.com/v1/detail?id=' + id,
        col_type: 'movie_3'
      });
    }
  }
} catch (err) {}
setResult(d);

