detail_find_rule:
js:
var d = [];
var res = request(input, { headers: { 'Accept': 'application/json' } });
try {
  var json = typeof res === 'string' ? JSON.parse(res) : res;
  var detail = json.data?.info || json.data || json;
  var seriesTitle = detail.title || detail.name || '';

  // 1. 顶部大剧名卡片
  d.push({
    title: '剧名：' + seriesTitle,
    desc: detail.intro || detail.summary || '',
    pic_url: detail.cover ? detail.cover + '@Referer=' + input : '',
    url: input,
    col_type: 'pic_1_card'
  });

  // 2. 线路与选集提取
  var episodes = detail.episodes || detail.video_list || [];
  d.push({
    title: '【默认播放线路】',
    col_type: 'text_1'
  });
  for (var i = 0; i < episodes.length; i++) {
    var ep = episodes[i];
    var epTitle = ep.title || ('第' + (i + 1) + '集');
    var playId = ep.id || ep.video_id || '';
    d.push({
      title: epTitle,
      url: 'lazy:https://api.example.com/v1/play_url?id=' + playId,
      col_type: 'text_3'
    });
  }
} catch (e) {}
setResult(d);

lazy:
js:
var res = request(input, { headers: { 'Accept': 'application/json' } });
var finalUrl = '';
try {
  var json = typeof res === 'string' ? JSON.parse(res) : res;
  finalUrl = json.data?.play_url || json.url || json.data?.stream || '';
} catch (e) {}
if (!finalUrl) {
  finalUrl = input;
}
finalUrl = finalUrl + ';{Referer@' + input + '&&User-Agent@PC}';
setResult({ url: finalUrl });
